typedef struct Point2D {
    double x;
    double y;
} Point2D;

Point2D createPoint2D(double x, double y) {
    Point2D p;
    p.x = x;
    p.y = y;
    return p;
}

typedef struct Rectangle {
    double x;
    double y;
    double width;
    double height;
} Rectangle;

double rectangleArea(const Rectangle* r) {
    return r ? r->width * r->height : 0.0;
}

typedef struct PersonRecord {
    int id;
    char name[64];
    int age;
    double gpa;
} PersonRecord;

void initPerson(PersonRecord* p, int id, const char* name, int age, double gpa) {
    if (!p) return;
    p->id = id;
    p->age = age;
    p->gpa = gpa;
    strncpy(p->name, name, 63);
    p->name[63] = '\0';
}

